import{_ as a,o as r,c as t,a2 as i}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{"outline":2},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1793111003000}'),n={name:"changelog.md"};function o(s,e,l,d,c,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>Features, improvements, and upgrade notes, from the first demo to PaperSeek 1.0.0-beta5.</p><h2 id="v1-0-0-beta5" tabindex="-1">1.0.0-beta5 <a class="header-anchor" href="#v1-0-0-beta5" aria-label="Permalink to &quot;1.0.0-beta5 {#v1-0-0-beta5}&quot;">​</a></h2><p>Results show where each paper was published and accepted, export straight into reference managers, and three Chinese databases join the sources. It upgrades earlier 1.0 betas in place, without a migration.</p><h3 id="venue-rankings-and-acceptance" tabindex="-1">Venue rankings and acceptance <a class="header-anchor" href="#venue-rankings-and-acceptance" aria-label="Permalink to &quot;Venue rankings and acceptance&quot;">​</a></h3><ul><li>Results carry CAS tiers and Top, JCR quartiles and Impact Factor, and CCF classes from <a href="https://github.com/hitfyd/ShowJCR" target="_blank" rel="noreferrer">ShowJCR</a>. The tables download to your computer on the first search; <strong>Settings → Data sources → Journal rankings</strong> shows their editions, updates them, or imports a local copy.</li><li>Conference acceptance shows venue, year, and Oral, Spotlight, or Poster, from PaperHub and OpenReview. Only main-track, NeurIPS Datasets &amp; Benchmarks, and TMLR acceptances count.</li><li>The results page filters by CAS tier or Top, JCR quartile, CCF class, and acceptance, and sorts by Impact Factor. Details also show OpenAlex open impact, which is not an Impact Factor.</li><li>Chinese journals are labelled PKU Core (北大核心), CSSCI source journal, CSSCI source collection, or CSSCI Extended, with each list&#39;s edition, from a list PaperSeek keeps. They are matched by Chinese title or former title, and each list is its own results filter.</li><li>The review paper picker shows the same labels and filters by them. Bibliometrics adds a <strong>Venue rankings</strong> view: tier, quartile, and class distributions and a table of ranked journals and conferences.</li></ul><h3 id="exports" tabindex="-1">Exports <a class="header-anchor" href="#exports" aria-label="Permalink to &quot;Exports&quot;">​</a></h3><ul><li>Complete and selected results export as BibTeX and RIS for Zotero, EndNote, and JabRef, with entry types for journal articles, conference papers, and preprints, and the conference acceptance in the note field. MCP <code>export_results</code> offers the same formats.</li><li>Records from OpenAlex, Crossref, PubMed, and Semantic Scholar keep ISSN, volume, issue, and pages when the source provides them.</li></ul><h3 id="data-sources" tabindex="-1">Data sources <a class="header-anchor" href="#data-sources" aria-label="Permalink to &quot;Data sources&quot;">​</a></h3><ul><li><strong>Wanfang Data</strong> (your AppKey), the <strong>National Social Sciences Database</strong>, and <strong>Chinese Medical Journals</strong> join the sources. Their searches are planned and queried in Chinese, each in its own query form.</li><li>The top-conference source also searches OpenReview and adds the accepted papers PaperHub lacks.</li></ul><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li>The network proxy moved to <strong>Settings → General</strong>. <strong>Remove proxies</strong> now removes them at once. OpenReview and the ShowJCR download use the data-source proxy scope.</li></ul><h3 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>A model reply missing its final brackets is closed and accepted instead of failing; a reply cut off inside a later paragraph is repaired rather than shortened.</li><li>A review section written with extra paragraphs keeps them, merged within the length limits and marked for review.</li><li>Review paper selection survives switching modules, and the temporary draft is released once the review is saved.</li><li>The MCP Docker image is built against its own release package.</li></ul><h3 id="upgrade-notes" tabindex="-1">Upgrade notes <a class="header-anchor" href="#upgrade-notes" aria-label="Permalink to &quot;Upgrade notes&quot;">​</a></h3><ul><li>From an earlier 1.0 beta, install 1.0.0b5 with pip or set <code>PAPERSEEK_VERSION=1.0.0-beta5</code> for Docker; your data needs no migration. See <a href="./self-hosting/upgrade#from-an-earlier-1-0-beta">upgrading from an earlier 1.0 beta</a>.</li><li>Venue labels are added when a search finishes, so earlier results have none; run a search again to label it. Recreate a bibliometric analysis to get its Venue rankings view.</li><li>The ranking tables download from GitHub. If GitHub is unreachable, set a proxy in <strong>Settings → General</strong> or import the files.</li></ul><p>See <a href="./guide/results">Results and history</a> and <a href="./guide/sources">Data sources</a> for details.</p><h2 id="v1-0-0-beta4" tabindex="-1">1.0.0-beta4 <a class="header-anchor" href="#v1-0-0-beta4" aria-label="Permalink to &quot;1.0.0-beta4 {#v1-0-0-beta4}&quot;">​</a></h2><p>Reviews start from your scope, can pick papers by topic, and say which papers they leave out and why. Ranking runs in parallel with separate progress for scores and reasons. It upgrades earlier 1.0 betas in place, without a migration.</p><h3 id="reviews" tabindex="-1">Reviews <a class="header-anchor" href="#reviews" aria-label="Permalink to &quot;Reviews&quot;">​</a></h3><ul><li>Setup now comes before paper selection. Choose chapter count, paragraphs per chapter, and paragraph length in the output language&#39;s unit; each length suggests how many papers to select.</li><li><strong>Auto-select by topic</strong> considers the first 256 papers with usable abstracts in search-rank order, picks papers that cover distinct themes, and gives a reason for each. It creates nothing and does not count as a writing task.</li><li>A review can use up to 256 papers, selected manually from the whole search.</li><li>Each generated paragraph plan uses at most 10 papers. Papers the outline leaves out are listed with a reason; add one to a chapter to bring it back.</li><li>While writing, a planned paper may be skipped only with a reason. The evidence check reviews each reason, marks doubtful ones, and marks a reason it could not check for manual review.</li><li>Citations a paragraph cannot place beside a specific claim are listed under it, also in Markdown and Word exports. Internal evidence IDs no longer appear in the text.</li><li>One failed section no longer stops the other sections; a retry writes only what is missing or needs revision.</li><li>Evidence quotations keep the abstract&#39;s wording and language and are shortened only when a shorter supporting passage can be found reliably.</li></ul><h3 id="search-ranking" tabindex="-1">Search ranking <a class="header-anchor" href="#search-ranking" aria-label="Permalink to &quot;Search ranking&quot;">​</a></h3><ul><li>Scoring and the &quot;Why it ranks&quot; explanations run in parallel batches, with separate progress for each part.</li><li>With your own key, the provider may receive several requests at once; its rate limits still apply.</li></ul><h3 id="upgrade-notes-1" tabindex="-1">Upgrade notes <a class="header-anchor" href="#upgrade-notes-1" aria-label="Permalink to &quot;Upgrade notes&quot;">​</a></h3><ul><li>From an earlier 1.0 beta, install 1.0.0b4 with pip or set <code>PAPERSEEK_VERSION=1.0.0-beta4</code> for Docker; your data needs no migration. See <a href="./self-hosting/upgrade#from-an-earlier-1-0-beta">upgrading from an earlier 1.0 beta</a>.</li><li>Reviews that have no written sections yet extract evidence again the next time you generate the outline. Reviews with written sections keep their evidence.</li></ul><p>See <a href="./guide/reviews">Literature reviews</a> for the workflow and limits.</p><h2 id="v1-0-0-beta3" tabindex="-1">1.0.0-beta3 <a class="header-anchor" href="#v1-0-0-beta3" aria-label="Permalink to &quot;1.0.0-beta3 {#v1-0-0-beta3}&quot;">​</a></h2><p>Searches that find nothing get a careful second try, data sources are paced across every running task, and you can route traffic through your own proxy. It upgrades earlier 1.0 betas in place, without a migration.</p><h3 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h3><ul><li>When a search finds no papers, PaperSeek tries up to two more queries. Each one builds on the earlier queries and their counts and is checked against your question first, so required concepts, relationships and constraints stay in place. If nothing turns up, the search ends with a notice that says why.</li><li>If the data source cannot be reached for one of these extra queries, the search ends with no papers and a notice instead of failing.</li><li>When the model proposes a query that already ran, it is shown the earlier result and asked once more before refinement stops.</li><li>The intent check accepts model replies that wrap their answer in extra text.</li></ul><h3 id="data-sources-1" tabindex="-1">Data sources <a class="header-anchor" href="#data-sources-1" aria-label="Permalink to &quot;Data sources&quot;">​</a></h3><ul><li>PubMed rate-limit messages are recognized as rate limits instead of network errors, and PaperSeek waits before trying again.</li><li>All running tasks share each source&#39;s pacing and cooldowns, including retries. arXiv receives one request every three seconds however many searches are running.</li><li>Ordinary failures are retried after about a second; only rate limits wait longer.</li><li>Web of Science is selectable again.</li></ul><h3 id="network-proxy" tabindex="-1">Network proxy <a class="header-anchor" href="#network-proxy" aria-label="Permalink to &quot;Network proxy&quot;">​</a></h3><ul><li><strong>Settings › Data sources › Network proxy</strong> routes requests through your own HTTP(S) proxy. Choose any of: model requests, sources that limit by network address (arXiv, Crossref, PaperHub, and PubMed or OpenAlex without a key), and other sources. Everything else follows your system proxy settings, and local model endpoints always connect directly.</li><li>Several proxies are used in turn. Addresses are stored encrypted on your machine, shown only by host and port, and removed by <strong>Clear saved keys</strong>.</li><li>Server deployments can set <code>PAPERSEEK_PROXY_URLS</code> and <code>PAPERSEEK_PROXY_SCOPE</code> instead. See <a href="./reference/configuration#network-proxy">Network proxy</a>.</li></ul><h3 id="running-tasks" tabindex="-1">Running tasks <a class="header-anchor" href="#running-tasks" aria-label="Permalink to &quot;Running tasks&quot;">​</a></h3><ul><li>Up to four searches and reviews run at the same time; the rest wait in the queue. <code>PAPERSEEK_MAX_CONCURRENT_RUNS</code> changes the limit, and <code>0</code> removes it. See <a href="./reference/configuration#concurrent-tasks">Concurrent tasks</a>.</li></ul><h3 id="upgrade-notes-2" tabindex="-1">Upgrade notes <a class="header-anchor" href="#upgrade-notes-2" aria-label="Permalink to &quot;Upgrade notes&quot;">​</a></h3><ul><li>From an earlier 1.0 beta, install 1.0.0b3 with pip or set <code>PAPERSEEK_VERSION=1.0.0-beta3</code> for Docker; your data needs no migration. See <a href="./self-hosting/upgrade#from-an-earlier-1-0-beta">upgrading from an earlier 1.0 beta</a>.</li><li>The new settings are optional. Without them, PaperSeek behaves as before, except that up to four tasks now run at once.</li></ul><h2 id="v1-0-0-beta2" tabindex="-1">1.0.0-beta2 <a class="header-anchor" href="#v1-0-0-beta2" aria-label="Permalink to &quot;1.0.0-beta2 {#v1-0-0-beta2}&quot;">​</a></h2><p>A maintenance release. Reviews and search rankings now carry on when a model gets part of its answer wrong, running searches stay in your history, and Docker Compose is private to your machine by default. It upgrades 1.0.0-beta1 in place, without a migration.</p><h3 id="reviews-1" tabindex="-1">Reviews <a class="header-anchor" href="#reviews-1" aria-label="Permalink to &quot;Reviews&quot;">​</a></h3><ul><li>A review no longer fails because a few papers come back without usable evidence. Those papers are left out of the outline and marked in the paper list; the rest of the review goes ahead, and preparing the outline again retries only them.</li><li>A paper keeps every quote that matches its abstract, even when the model gets another quote wrong. Quotes stitched together with an ellipsis (…) are checked as separate passages instead of being rejected.</li><li>The outline no longer stops on a paper without checked evidence. That paper is dropped from the plan, and a paragraph left without sources is given new ones from the checked evidence.</li></ul><h3 id="search-ranking-1" tabindex="-1">Search ranking <a class="header-anchor" href="#search-ranking-1" aria-label="Permalink to &quot;Search ranking&quot;">​</a></h3><ul><li>When the model scores only some of the candidates, the scores it gave are kept and only the missing papers are asked for again. Papers that still have no score are listed after the scored ones in their original order, and the search reports a warning.</li><li>&quot;Why it ranks&quot; explanations are requested in smaller groups, so long explanations, Chinese ones especially, are no longer cut off. Papers a reply skipped are asked for once more.</li></ul><h3 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h3><ul><li>Queued and running searches now appear in the search history, also after you reload the page, and cannot be deleted while they run.</li></ul><h3 id="self-hosting" tabindex="-1">Self-hosting <a class="header-anchor" href="#self-hosting" aria-label="Permalink to &quot;Self-hosting&quot;">​</a></h3><ul><li>The supplied Docker Compose file publishes PaperSeek on this machine only (127.0.0.1:8765). To open it from other devices, set <code>PAPERSEEK_HOST=0.0.0.0</code> in <code>.env</code> and protect access; <code>PAPERSEEK_PORT</code> still changes the port.</li><li>The MCP Docker image builds again from a clean checkout.</li><li>Third-party notice tables display correctly in every distribution.</li></ul><h3 id="documentation-site" tabindex="-1">Documentation site <a class="header-anchor" href="#documentation-site" aria-label="Permalink to &quot;Documentation site&quot;">​</a></h3><ul><li>On the home page, a resting finger or the end of a trackpad swipe no longer jumps to another section.</li></ul><h3 id="upgrade-notes-3" tabindex="-1">Upgrade notes <a class="header-anchor" href="#upgrade-notes-3" aria-label="Permalink to &quot;Upgrade notes&quot;">​</a></h3><ul><li>From 1.0.0-beta1, install 1.0.0b2 with pip or set <code>PAPERSEEK_VERSION</code> to <code>1.0.0-beta2</code> for Docker; your data needs no migration. See <a href="./self-hosting/upgrade#from-an-earlier-1-0-beta">upgrading from an earlier 1.0 beta</a>.</li><li>If you reach a Docker deployment from another device, take the new <code>compose.yaml</code> and set <code>PAPERSEEK_HOST</code> as described above.</li></ul><h2 id="v1-0-0-beta" tabindex="-1">1.0.0-beta1 <a class="header-anchor" href="#v1-0-0-beta" aria-label="Permalink to &quot;1.0.0-beta1 {#v1-0-0-beta}&quot;">​</a></h2><p>PaperSeek 1.0.0-beta1 is a <strong>complete architectural refactor with breaking changes</strong>. It rebuilds the execution model, frontend, storage boundaries, and distribution around a shared research application, with an explicit migration path for existing user data.</p><h3 id="three-modules-and-independent-histories" tabindex="-1">Three modules and independent histories <a class="header-anchor" href="#three-modules-and-independent-histories" aria-label="Permalink to &quot;Three modules and independent histories&quot;">​</a></h3><ul><li>A redesigned workspace: Search, Bibliometrics, and Reviews in a collapsible sidebar with each module&#39;s history, and the account at the bottom.</li><li>Settings pages for model APIs, data sources, general preferences, and the user&#39;s data: clear saved keys or all history, each after typing a confirmation phrase. Running tasks are stopped before history is cleared.</li><li>Preliminary bibliometrics over the actually retrieved deduplicated candidate corpus; native-field coverage, keyword co-occurrence, bounded bibliographic coupling, cached networks, and independent exports. LLM scoring remains a subset.</li><li>Review citation evidence alongside papers, outline, and draft; new reviews preserve available source graph snapshots.</li><li>Rename history records; the original question and settings stay unchanged.</li></ul><p>Install it from pip as <code>1.0.0b1</code>; the Docker image tag is <code>1.0.0-beta1</code>.</p><h3 id="paperseek-online" tabindex="-1">PaperSeek online <a class="header-anchor" href="#paperseek-online" aria-label="Permalink to &quot;PaperSeek online&quot;">​</a></h3><ul><li>Sign in for PaperSeek Service: built-in models, no keys, and free daily credits during the public beta (20 a day). A search or an analysis uses 1 credit and a review 5, deducted when the task starts; a failed or cancelled task returns them.</li><li>Your own key: save model connections and data-source keys to your account in Settings; tasks then use your API and no credits. Every data source that takes a key (OpenAlex, PubMed, Semantic Scholar, Google Scholar, Web of Science) requires one in this mode; arXiv, Crossref, and PaperHub work without.</li><li>Without signing in, run one temporary search with your own key typed into the form. It is held in memory only and never saved.</li></ul><h3 id="architecture-rebuilt-around-clear-responsibilities" tabindex="-1">Architecture rebuilt around clear responsibilities <a class="header-anchor" href="#architecture-rebuilt-around-clear-responsibilities" aria-label="Permalink to &quot;Architecture rebuilt around clear responsibilities&quot;">​</a></h3><ul><li>Separate <code>paperseek_core</code> for retrieval, query iteration, citation expansion, ranking, and source/model protocols; <code>paperseek_app</code> for run submission, execution, persistence, and queries; and deployment adapters for Community and the online edition.</li><li>Use one application layer across Web, CLI, HTTP API, and MCP. The search core is independent of FastAPI, authentication, SQLite, and Supabase.</li><li>The online edition and Community share one search implementation and the same research pages.</li><li>Rebuild the frontend with Vue 3, TypeScript, and Vite. Shared research pages use the versioned <code>/api/v1</code> contract; generated API types keep frontend and backend interfaces aligned.</li><li>Use explicit asynchronous workflows and httpx clients, with Pydantic models at the boundaries. Retire obsolete runtime entry points.</li></ul><h3 id="persistent-tasks-cancellation-and-recovery" tabindex="-1">Persistent tasks, cancellation, and recovery <a class="header-anchor" href="#persistent-tasks-cancellation-and-recovery" aria-label="Permalink to &quot;Persistent tasks, cancellation, and recovery&quot;">​</a></h3><ul><li>Make saved searches database-backed runs with worker leases, ordered events, checkpoints, and result artifacts. Community can resume compatible interrupted work from committed checkpoints.</li><li>Restore saved pages from a run snapshot and replayed events, then follow updates through SSE. Reconnecting the browser does not submit a new search.</li><li>Coordinate cancellation and lease ownership so an obsolete worker or a late provider response cannot commit results after cancellation.</li><li>Separate source/model failures from persistence failures: optional retrieval or ranking stages can report warnings and fall back, while a failed result commit cannot be presented as success.</li><li>Introduce versioned SQLite migrations through Alembic and explicit migration commands. Community uses SQLite and local files. A signed-out online search is temporary and is not added to history.</li></ul><p>Community can run the API and an embedded worker as one local service, or run them separately. Reconnecting the browser restores the page; an interrupted task resumes from its checkpoint.</p><h3 id="a-complete-research-workspace" tabindex="-1">A complete research workspace <a class="header-anchor" href="#a-complete-research-workspace" aria-label="Permalink to &quot;A complete research workspace&quot;">​</a></h3><ul><li>Vue 3 interface with English and Chinese, consistent navigation, and task-stage progress.</li><li>Question-driven query iteration, bounded retrieval, relevance ranking, and transparent search history.</li><li>Eight scholarly source integrations, with source-specific fields and access settings.</li><li>Local fusion, Embedding + Rerank, and System One preliminary-ranking options.</li><li>Citation expansion and an interactive citation map through OpenAlex.</li><li>Saved runs, filtering, selection, and complete CSV/JSON exports.</li><li><strong>Experimental</strong> abstract-based reviews with editable outlines, section writing, versions, citations, and Markdown/Word/BibTeX exports.</li></ul><h3 id="one-application-several-entry-points" tabindex="-1">One application, several entry points <a class="header-anchor" href="#one-application-several-entry-points" aria-label="Permalink to &quot;One application, several entry points&quot;">​</a></h3><p>The Web UI, six-command CLI, versioned HTTP API, and independent same-version MCP adapter reuse the same application services. Community keeps data in local SQLite and files. The online product adds accounts, service models, queueing, and isolated storage.</p><h3 id="upgrade-notes-4" tabindex="-1">Upgrade notes <a class="header-anchor" href="#upgrade-notes-4" aria-label="Permalink to &quot;Upgrade notes&quot;">​</a></h3><p>Python <strong>3.12+</strong> is required. Old Python imports, internal APIs, frontend endpoints, and retired CLI/configuration entries are not retained. Supported 0.2 data and environment settings have explicit migration commands; migrated configuration uses the new names without a legacy runtime fallback. See the <a href="./self-hosting/upgrade">migration guide</a> and <a href="./developers/contributing#architecture">architecture notes</a>.</p><p>Search uses abstracts and metadata provided by the source. Standalone cross-source abstract and citation-count enrichment are no longer part of the configuration.</p><h2 id="v0-2-1" tabindex="-1">0.2.1 <a class="header-anchor" href="#v0-2-1" aria-label="Permalink to &quot;0.2.1 {#v0-2-1}&quot;">​</a></h2><p>July 5, 2026 · Provider routing and hosted service updates</p><h3 id="models-and-retrieval" tabindex="-1">Models and retrieval <a class="header-anchor" href="#models-and-retrieval" aria-label="Permalink to &quot;Models and retrieval&quot;">​</a></h3><ul><li>Expanded provider routing with NVIDIA NIM and OpenRouter support.</li><li>Updated PaperHub query handling and candidate-pool narrowing.</li></ul><h3 id="reliability" tabindex="-1">Reliability <a class="header-anchor" href="#reliability" aria-label="Permalink to &quot;Reliability&quot;">​</a></h3><ul><li>Corrected NVIDIA reranker endpoint handling and improved ranking fallbacks.</li><li>Added retries for transient API failures.</li><li>Unified shared LLM route logging across providers.</li></ul><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>Expanded PaperSeek Service documentation, including hosted data-source credentials and release notes.</li></ul><p><a href="https://github.com/paperseek/paperseek/releases/tag/v0.2.1" target="_blank" rel="noreferrer">Original release notes</a></p><h2 id="v0-2-0" tabindex="-1">0.2.0 <a class="header-anchor" href="#v0-2-0" aria-label="Permalink to &quot;0.2.0 {#v0-2-0}&quot;">​</a></h2><p>July 4, 2026 · More sources and multi-lane retrieval</p><h3 id="search-and-ranking" tabindex="-1">Search and ranking <a class="header-anchor" href="#search-and-ranking" aria-label="Permalink to &quot;Search and ranking&quot;">​</a></h3><ul><li>Expanded the source lineup with arXiv, Semantic Scholar, PubMed, computer-science conferences, and Crossref.</li><li>Introduced source-specific queries, intent recognition, and feedback across query iterations.</li><li>Added preliminary ranking before LLM scoring. Retrieval combines relevance, influence or citations, freshness, and local quality signals, using RRF, BM25/term coverage, and local hashing embeddings.</li><li>Added optional OpenAI-compatible embedding and reranker services.</li></ul><h3 id="online-accounts" tabindex="-1">Online accounts <a class="header-anchor" href="#online-accounts" aria-label="Permalink to &quot;Online accounts&quot;">​</a></h3><ul><li>Updated email registration and sign-in, with GitHub and ModelScope OAuth.</li><li>Introduced a daily allowance of 20 successful searches for signed-in users at that release.</li></ul><p><a href="https://github.com/paperseek/paperseek/releases/tag/v0.2.0" target="_blank" rel="noreferrer">Original release notes</a></p><h2 id="v0-1-1" tabindex="-1">0.1.1 <a class="header-anchor" href="#v0-1-1" aria-label="Permalink to &quot;0.1.1 {#v0-1-1}&quot;">​</a></h2><p>June 6, 2026 · Discipline filters and bilingual use</p><h3 id="search-filters" tabindex="-1">Search filters <a class="header-anchor" href="#search-filters" aria-label="Permalink to &quot;Search filters&quot;">​</a></h3><ul><li>Added source-specific disciplines using OpenAlex Fields and Web of Science Categories.</li><li>Applied OpenAlex discipline filters to both initial retrieval and citation expansion.</li><li>Fixed handling of OpenAlex Field labels containing commas across the CLI, environment settings, API, and interface selections.</li></ul><h3 id="interface-and-packaging" tabindex="-1">Interface and packaging <a class="header-anchor" href="#interface-and-packaging" aria-label="Permalink to &quot;Interface and packaging&quot;">​</a></h3><ul><li>Added Chinese/English switching and refreshed user and deployment documentation.</li><li>Reorganized the community package around its self-contained core.</li><li>Included Docker/runtime packaging fixes, history improvements, and provider updates.</li></ul><p><a href="https://github.com/paperseek/paperseek/releases/tag/v0.1.1" target="_blank" rel="noreferrer">Original release notes</a></p><h2 id="v0-1-0" tabindex="-1">0.1.0 <a class="header-anchor" href="#v0-1-0" aria-label="Permalink to &quot;0.1.0 {#v0-1-0}&quot;">​</a></h2><p>June 2, 2026 · First demo release</p><p>The first release established the literature-discovery workflow:</p><ul><li>Research questions in Chinese or English, LLM-generated queries, and iterative widening or narrowing based on source results.</li><li>Metadata collection and LLM relevance scores with brief explanations.</li><li>OpenAlex citation expansion and an interactive map with dragging, zooming, and panning.</li><li>Web results with search, filters, selection, and CSV export.</li><li>Local Web UI, command-line use, Docker deployment, and an optional Agent Skill.</li><li>Support for hosted model providers, compatible endpoints, and local Ollama.</li></ul><p>The demo release linked to its commit history without a separate feature list. This summary follows the <a href="https://github.com/paperseek/paperseek/blob/v0.1.0/README.md" target="_blank" rel="noreferrer">README at the 0.1.0 tag</a>.</p><p><a href="https://github.com/paperseek/paperseek/releases/tag/v0.1.0" target="_blank" rel="noreferrer">Original release</a> · <a href="https://github.com/paperseek/paperseek/commits/v0.1.0/" target="_blank" rel="noreferrer">Code history</a></p>',100)])])}const g=a(n,[["render",o]]);export{p as __pageData,g as default};
